#include <iostream>
#include <vector>
#include <string>
#include <sstream>
#include <algorithm>

using namespace std;

int maxSubArray(vector<int>& nums) {
    int res = nums[0], cur = 0;
    for (int n : nums) {
        cur = max(cur + n, n);
        res = max(res, cur);
    }
    return res;
}

int main() {
    string line; if (!getline(cin, line)) return 0;
    for (char &c : line) if (c == '[' || c == ']' || c == ',') c = ' ';
    stringstream ss(line);
    int val; vector<int> nums;
    while (ss >> val) nums.push_back(val);
    if (nums.empty()) return 0;
    cout << maxSubArray(nums) << endl;
    return 0;
}

